const norm = $('Eingabe normalisieren').first().json;
const profil = $('Profil laden').first().json || {};
const klein = x => String(x || '').trim().toLowerCase();
const zahl = v => { const x = Number(v); return Number.isFinite(x) ? x : 0; };
const qus = $('Grocy-Einheiten laden').all().map(i => i.json).filter(q => q && q.id);
const quCode = {};
for (const q of qus) quCode[q.id] = klein(q.name) === 'gramm' ? 'g' : klein(q.name) === 'milliliter' ? 'ml' : klein(q.name) === 'stück' ? 'stk' : q.name;
const nw = {};
for (const i of $('Nährwerte laden').all()) if (i.json && i.json.grocy_product_id) nw[i.json.grocy_product_id] = i.json;
const bestand = $('Grocy-Bestand laden').all().map(i => i.json).filter(r => r && r.product_id && Number(r.amount) > 0);
const zone = 'Europe/Berlin';
const heute = DateTime.now().setZone(zone).startOf('day');

const vorrat = bestand.map(r => {
  const p = r.product || {};
  const m = r.best_before_date && !String(r.best_before_date).startsWith('2999') ? DateTime.fromISO(String(r.best_before_date).slice(0, 10), { zone }) : null;
  const n = nw[r.product_id] || {};
  const e = { product_id: Number(r.product_id), name: p.name, menge: Math.round(Number(r.amount) * 10) / 10, einheit: quCode[p.qu_id_stock] || 'stk', tage_bis_mhd: m ? Math.round(m.diff(heute, 'days').days) : null };
  if (n.kcal_100 != null) e.pro_100g = { kcal: n.kcal_100, p: n.protein_100, f: n.fett_100, kh: n.kh_100 };
  if (n.gramm_pro_stk) e.gramm_pro_stk = n.gramm_pro_stk;
  if (n.nutriscore) e.nutriscore = n.nutriscore;
  if (n.nova) e.nova = n.nova;
  return e;
}).sort((a, b) => (a.tage_bis_mhd ?? 999) - (b.tage_bis_mhd ?? 999));

// Tagesziele (fehlende Makros sinnvoll ergänzen)
const hatZiele = zahl(profil.kcal) > 0;
const ziel = hatZiele
  ? { kcal: zahl(profil.kcal), p: zahl(profil.protein_g), f: zahl(profil.fett_g), kh: zahl(profil.kh_g) }
  : { kcal: 2000, p: 0, f: 0, kh: 0 };
if (!ziel.p) ziel.p = Math.round(ziel.kcal * 0.3 / 4);
if (!ziel.f) ziel.f = Math.round(ziel.kcal * 0.28 / 9);
if (!ziel.kh) ziel.kh = Math.round(Math.max(0, ziel.kcal - ziel.p * 4 - ziel.f * 9) / 4);

// Verteilung der Tagesziele auf die Mahlzeiten
const VERTEILUNG = {
  1: [['Mittag', 1]],
  2: [['Frühstück', 0.45], ['Abend', 0.55]],
  3: [['Frühstück', 0.3], ['Mittag', 0.35], ['Abend', 0.35]],
  4: [['Frühstück', 0.25], ['Mittag', 0.3], ['Abend', 0.3], ['Snack', 0.15]],
  5: [['Frühstück', 0.22], ['Mittag', 0.28], ['Abend', 0.28], ['Snack', 0.11], ['Snack 2', 0.11]],
};
const anzahl = Math.max(1, Math.min(5, Math.round(zahl(profil.mahlzeiten_pro_tag)) || 3));
const slots = VERTEILUNG[anzahl].map(([name, anteil]) => ({
  name, anteil,
  kcal: Math.round(ziel.kcal * anteil / 10) * 10,
  p: Math.round(ziel.p * anteil), f: Math.round(ziel.f * anteil), kh: Math.round(ziel.kh * anteil),
}));
const slotText = slots.map(s => '- ' + s.name + ': ca. ' + s.kcal + ' kcal, ' + s.p + ' g Protein, ' + s.f + ' g Fett, ' + s.kh + ' g KH').join('\n');
const ziele_text = (hatZiele ? 'Ziel pro Tag: ' : 'Keine Ziele hinterlegt, Standard: ') + ziel.kcal + ' kcal · P ' + ziel.p + ' g · F ' + ziel.f + ' g · KH ' + ziel.kh + ' g';
const kcalProMahlzeit = ziel.kcal / anzahl;
const start = heute.plus({ days: 1 });

let aufgabe;
if (norm.modus === 'wochenplan') {
  aufgabe = 'AUFGABE: Erstelle einen Wochenplan für 7 Tage von ' + start.toISODate() + ' bis ' + start.plus({ days: 6 }).toISODate()
    + ' mit genau diesen ' + anzahl + ' Mahlzeiten pro Tag: ' + slots.map(s => s.name).join(', ') + ' (also ' + (7 * anzahl) + ' Rezepte). '
    + 'Setze bei jedem Rezept "tag" auf das Datum und "mahlzeit" exakt auf einen dieser Namen.\n'
    + 'Verplane zuerst Vorrat, der bald abläuft (kleine tage_bis_mhd zuerst).\n'
    + 'Abwechslung: Jedes Mittag- oder Abendgericht höchstens 2x pro Woche (Meal-Prep: ein Abendessen darf am nächsten Tag als Mittag wiederkommen). '
    + 'Frühstück und Snacks dürfen sich wiederholen, aber nutze mindestens 3 verschiedene Frühstücke.';
} else {
  aufgabe = 'AUFGABE: Schlage genau 3 einfache, gesunde Rezepte (je 1 Portion) für verschiedene Mahlzeiten vor, die überwiegend den vorhandenen Vorrat nutzen. '
    + 'Priorisiere Zutaten mit tage_bis_mhd <= 3. Setze "tag" auf ' + heute.toISODate() + ' und "mahlzeit" auf einen dieser Namen: ' + slots.map(s => s.name).join(', ') + '.';
}
if (norm.hinweis) aufgabe += '\nZusatzwunsch des Nutzers (hat Vorrang, solange gesund): ' + norm.hinweis;

const proteinAnteil = ziel.p * 4 / ziel.kcal;
const ziele = 'ZIELE PRO MAHLZEIT (wähle die Portionsgrößen danach, 1 Rezept = 1 Portion):\n' + slotText
  + '\nSumme pro Tag: ' + ziel.kcal + ' kcal, ' + ziel.p + ' g Protein, ' + ziel.f + ' g Fett, ' + ziel.kh + ' g KH.'
  + (proteinAnteil >= 0.2
    ? '\nPROTEIN: Jedes Rezept braucht mindestens eine eiweißreiche Hauptzutat (Hähnchen, Pute, mageres Rind, Fisch, Garnelen, Eier, Magerquark, Skyr, Hüttenkäse, Tofu, Tempeh, Seitan, Proteinpulver), '
      + 'die allein schon etwa zwei Drittel des Protein-Ziels der Mahlzeit liefert. Hülsenfrüchte, Nüsse und Joghurt allein reichen dafür nicht.'
    : '')
  + (kcalProMahlzeit >= 900
    ? '\nDie Portionen sind groß. Erreiche die Kalorien mit energiedichten, gesunden Zutaten (Haferflocken, Nüsse, Nussmus, Olivenöl, Avocado, Reis, Vollkornnudeln, Kartoffeln, Käse, Vollmilch, Skyr, Hülsenfrüchte) statt mit riesigen Gemüsemengen.'
    : '');

const format = 'ANTWORTFORMAT (nur dieses JSON, nichts anderes):\n'
  + '{"hinweis":"1 kurzer Satz, welche Zutaten zuerst verbraucht werden sollten",'
  + '"rezepte":[{"titel":"Porridge mit Banane und Erdnussmus","tag":"YYYY-MM-DD","mahlzeit":"Frühstück","dauer_min":10,'
  + '"zutaten":['
  + '{"product_id":null,"name":"Haferflocken","menge":100,"einheit":"g","packung":500,"pro_100g":{"kcal":372,"p":13.5,"f":7,"kh":58.7}},'
  + '{"product_id":null,"name":"Banane","menge":1,"einheit":"stk","gramm":120,"pro_100g":{"kcal":93,"p":1.2,"f":0.2,"kh":20}},'
  + '{"product_id":null,"name":"Erdnussmus","menge":20,"einheit":"g","packung":350,"basis":true,"pro_100g":{"kcal":620,"p":25,"f":50,"kh":12}}'
  + '],"anleitung":["Schritt 1","Schritt 2"]}]}\n'
  + 'REGELN ZU DEN ZUTATEN:\n'
  + '- einheit ist "g", "ml" oder "stk". Alles, was man im Supermarkt stückweise kauft (Eier, Bananen, Äpfel, Zwiebeln, Paprika, Zucchini, Avocados, Brötchen, Wraps, Brokkoli, Salatköpfe …), als "stk" mit ganzen oder halben Stück und zusätzlich "gramm" = Gesamtgewicht dieser Stücke.\n'
  + '- Bei "g"/"ml" zusätzlich "packung" = übliche Packungsgröße im deutschen Supermarkt in derselben Einheit (z.B. Haferflocken 500, Skyr 450, Magerquark 500, Hähnchenbrustfilet 400, Reis 1000, Milch 1000, Passata 500, Kichererbsen Dose 400). '
  + 'Bei "stk" nur für Ware, die in Packungen verkauft wird, "packung" = Stück pro Packung (Eier 10, Brötchen 6, Wraps 6). Brot und Toast immer in "g" (z.B. 2 Scheiben = 100 g, packung 500).\n'
  + '- Reste-Mahlzeiten (Meal-Prep) bekommen denselben Titel wie das Original und dessen vollständige Zutatenliste für diese Portion, niemals das fertige Gericht als Zutat.\n'
  + '- Zutatennamen schlicht und einheitlich halten (immer "Kartoffeln", nicht "Kartoffeln (Rest)"); gleiche Zutat = gleicher Name im ganzen Plan.\n'
  + '- product_id nur aus dem VORRAT und dann exakt dessen Einheit verwenden; pro_100g ist dort schon bekannt und kann entfallen.\n'
  + '- Zutaten, die nicht im Vorrat sind: "product_id": null und "pro_100g" mit typischen Nährwerten pro 100 g laut Nährwerttabelle (roh bzw. wie eingekauft).\n'
  + '- Öl, Butter, Nussmus, Honig, Sahne, Käse usw. IMMER mit Menge aufführen, sie liefern Kalorien. Grundzutaten, die man meist zu Hause hat (Öl, Butter, Honig, Nussmus, Brühe, Senf, Essig, Sojasauce), mit "basis": true markieren. Salz, Pfeffer, Gewürze, Knoblauch und Kräuter weglassen.\n'
  + '- Max. 8 Zutaten pro Rezept (ohne basis), max. 30 Minuten. kcal und Makros NICHT selbst ausrechnen, das macht das System aus deinen Mengen und pro_100g.\n'
  + '- Bevorzuge Produkte mit Nutri-Score A/B und NOVA 1-3; Nutri-Score D/E oder NOVA 4 nur sparsam.';

const system = 'Du bist Ernährungscoach und Koch. Alles muss gesund sein: viel Gemüse, Hülsenfrüchte, Vollkorn, mageres Protein, gesunde Fette, '
  + 'wenig Zucker und wenig stark verarbeitete Lebensmittel. Rezepte sind einfache Alltagsküche. Deine Nährwertangaben pro 100 g müssen realistischen Tabellenwerten entsprechen. '
  + 'Vorlieben des Nutzers: ' + (profil.vorlieben || 'keine') + '. Antworte ausschließlich mit gültigem JSON.';

const prompt = aufgabe + '\n\n' + ziele + '\n\nVORRAT (sortiert nach Ablaufdatum):\n' + JSON.stringify(vorrat) + '\n\n' + format;

return [{ json: { modus: norm.modus, chat_id: String(profil.chat_id || ''), ziel, slots, anzahl, ziele_text, vorrat, system, prompt } }];

const ctx = $('Kontext bauen').first().json;
const res = $('MiniMax plant Rezepte').first().json;
const choice = (res.choices && res.choices[0]) || {};
let s = String((choice.message && choice.message.content) || '');
if (s.includes('</think>')) s = s.split('</think>').pop();
s = s.replace(/```(?:json)?/g, '');
const a = s.indexOf('{');
const b = s.lastIndexOf('}');
const abgeschnitten = choice.finish_reason === 'length' ? ' (Antwort abgeschnitten, max_tokens zu klein)' : '';
if (a < 0 || b < 0) throw new Error('KI-Antwort enthält kein JSON' + abgeschnitten + ': ' + s.slice(0, 300));
// JSON der KI lesen; typische Formatfehler („1.“ ohne Nachkommastelle, Dezimalkomma, Komma vor Klammer) einmal reparieren
const jsonLesen = text => {
  const roh = text.slice(text.indexOf('{'), text.lastIndexOf('}') + 1);
  try { return JSON.parse(roh); } catch (e) {
    const repariert = roh.replace(/(\d)\.(?=\s*[,}\]])/g, '$1').replace(/(:\s*-?\d+),(\d+)(?=\s*[,}\]])/g, '$1.$2').replace(/,(\s*[}\]])/g, '$1');
    try { return JSON.parse(repariert); } catch (e2) { throw e; }
  }
};
let data;
try { data = jsonLesen(s); } catch (e) { throw new Error('KI-JSON ungültig' + abgeschnitten + ': ' + e.message); }
const rezepteRoh = Array.isArray(data.rezepte) ? data.rezepte : [];
if (!rezepteRoh.length) throw new Error('KI hat keine Rezepte geliefert');

const zone = 'Europe/Berlin';
const heute = DateTime.now().setZone(zone).toISODate();
const esc = t => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const klein = x => String(x || '').trim().toLowerCase();
const zahl = v => { const x = Number(v); return Number.isFinite(x) ? x : 0; };
const clamp = (x, lo, hi) => Math.min(hi, Math.max(lo, x));
// „Kartoffeln (festkochend)“, „Lachs … (Rest vom 28.)“ → Grundname ohne Klammerzusatz
const grundname = name => String(name || '').replace(/\s*\([^)]*\)\s*/g, ' ').replace(/\s+/g, ' ').trim() || String(name || '');
const ziel = ctx.ziel;
const slotNach = {};
for (const sl of ctx.slots) slotNach[klein(sl.name)] = sl;
const slotStandard = { kcal: ziel.kcal / ctx.anzahl, p: ziel.p / ctx.anzahl };
const inv = {};
for (const v of ctx.vorrat) inv[v.product_id] = v;

// REWE-Produkte zu den Zutaten: Kandidaten vom rewe-service, Auswahl durch MiniMax. Fehlt etwas, geht es ohne REWE weiter.
const knoten = name => { try { return $(name).first().json || {}; } catch (e) { return {}; } };
const reweKandidaten = knoten('REWE-Kandidaten').kandidaten || {};
let reweWahl = {};
try {
  const w = knoten('MiniMax wählt Produkte');
  let t = String((((w.choices || [])[0] || {}).message || {}).content || '');
  if (t.includes('</think>')) t = t.split('</think>').pop();
  t = t.replace(/```(?:json)?/g, '');
  reweWahl = (JSON.parse(t.slice(t.indexOf('{'), t.lastIndexOf('}') + 1)) || {}).wahl || {};
} catch (e) { reweWahl = {}; }
const reweProdukt = name => {
  const id = reweWahl[name];
  return id ? ((reweKandidaten[name] || []).find(p => String(p.rewe_product_id) === String(id)) || null) : null;
};

// Nährwerte pro 100 g prüfen: kcal muss grob zu P/F/KH passen (Atwater 4/9/4)
const naehr = q => {
  if (!q || typeof q !== 'object') return null;
  const p = clamp(zahl(q.p ?? q.protein), 0, 100), f = clamp(zahl(q.f ?? q.fett), 0, 100), kh = clamp(zahl(q.kh), 0, 100);
  let kcal = zahl(q.kcal);
  const atwater = 4 * p + 9 * f + 4 * kh;
  if (atwater > 0 && (kcal <= 0 || Math.abs(kcal - atwater) / atwater > 0.25)) kcal = atwater;
  if (kcal <= 0) return null;
  return { kcal: Math.min(kcal, 900), p, f, kh };
};

const einheitNorm = e => {
  e = klein(e);
  if (['g', 'gramm', 'gr'].includes(e)) return 'g';
  if (['ml', 'milliliter'].includes(e)) return 'ml';
  if (['kg', 'l'].includes(e)) return e;
  return 'stk';
};

const zutatAufbereiten = z => {
  const v = z.product_id != null ? inv[Number(z.product_id)] : null;
  const rp = v ? null : reweProdukt(String(z.name || '').replace(/\s*\(Rest[^)]*\)/gi, '').trim());
  let einheit = v ? v.einheit : einheitNorm(z.einheit);
  let menge = zahl(z.menge);
  if (einheit === 'kg') { einheit = 'g'; menge *= 1000; }
  if (einheit === 'l') { einheit = 'ml'; menge *= 1000; }
  let gProEinheit = 1;
  if (einheit !== 'g' && einheit !== 'ml') {
    const ausVorrat = v && zahl(v.gramm_pro_stk);
    const ausKi = menge > 0 && zahl(z.gramm) > 0 ? zahl(z.gramm) / menge : 0;
    gProEinheit = ausVorrat || ausKi || 100;
  }
  return {
    product_id: v ? v.product_id : null,
    name: String(z.name || (v && v.name) || '?').trim(),
    menge, einheit, g_pro_einheit: gProEinheit,
    // Nährwerte: Vorrat (OpenFoodFacts/REWE) > gewähltes REWE-Produkt > Schätzung der KI
    pro_100g: naehr(v && v.pro_100g)
      || (rp && rp.kcal_100 != null ? naehr({ kcal: rp.kcal_100, p: rp.protein_100, f: rp.fett_100, kh: rp.kh_100 }) : null)
      || naehr(z.pro_100g),
    rewe: rp,
    packung: (einheit === 'g' || einheit === 'ml')
      ? (zahl(z.packung) >= 10 ? zahl(z.packung) * (klein(z.einheit) === 'kg' || klein(z.einheit) === 'l' ? 1000 : 1) : 0)
      : (zahl(z.packung) >= 2 ? Math.round(zahl(z.packung)) : /^eier?\b/i.test(String(z.name || '').trim()) ? 10 : 0),
    basis: !v && z.basis === true,
  };
};

const makros = zl => zl.reduce((acc, z) => {
  if (!z.pro_100g) return acc;
  const f = z.menge * z.g_pro_einheit / 100;
  acc.kcal += z.pro_100g.kcal * f; acc.p += z.pro_100g.p * f; acc.f += z.pro_100g.f * f; acc.kh += z.pro_100g.kh * f;
  return acc;
}, { kcal: 0, p: 0, f: 0, kh: 0 });

// Zutaten nach dominantem Energieträger gruppieren: Protein, Fett oder Kohlenhydrate
const gruppe = z => {
  if (!z.pro_100g) return 'kh';
  const n = z.pro_100g;
  if (n.p * 4 / n.kcal >= 0.35) return 'p';
  if (n.f * 9 / n.kcal >= 0.5) return 'f';
  return 'kh';
};

// Mengenfaktor je Gruppe so wählen, dass kcal, Protein, Fett und KH möglichst nah am Ziel liegen
// (gewichtete Kleinste-Quadrate mit Faktor-Grenzen, gelöst per Koordinatenabstieg).
const GEWICHT = { kcal: 4, p: 2, f: 1, kh: 1 };
const skalieren = (zl, t, lo, hi) => {
  const G = ['p', 'f', 'kh'].map(g => ({ g, m: makros(zl.filter(z => gruppe(z) === g)) })).filter(x => x.m.kcal > 0);
  if (!G.length || !(t.kcal > 0)) return;
  const keys = Object.keys(GEWICHT).filter(k => t[k] > 0);
  const w = {};
  for (const k of keys) w[k] = GEWICHT[k] / (t[k] * t[k]);
  const x = G.map(() => clamp(t.kcal / G.reduce((acc, y) => acc + y.m.kcal, 0), lo, hi));
  for (let iter = 0; iter < 60; iter++) {
    for (let i = 0; i < G.length; i++) {
      let zaehler = 0, nenner = 0;
      for (const k of keys) {
        const rest = G.reduce((acc, y, j) => acc + (j === i ? 0 : x[j] * y.m[k]), 0);
        zaehler += w[k] * G[i].m[k] * (t[k] - rest);
        nenner += w[k] * G[i].m[k] * G[i].m[k];
      }
      if (nenner > 0) x[i] = clamp(zaehler / nenner, lo, hi);
    }
  }
  const faktor = {};
  G.forEach((y, i) => { faktor[y.g] = x[i]; });
  for (const z of zl) z.menge *= faktor[gruppe(z)] ?? 1;
};

const runden = z => {
  if (z.einheit === 'g' || z.einheit === 'ml') {
    const step = z.menge < 20 ? 1 : z.menge < 100 ? 5 : 10;
    z.menge = Math.max(step, Math.round(z.menge / step) * step);
  } else if (z.g_pro_einheit <= 70) {
    z.menge = Math.max(1, Math.round(z.menge));
  } else {
    z.menge = Math.max(0.5, Math.round(z.menge * 2) / 2);
  }
};

// Reste-Mahlzeiten: Führt die KI das fertige Gericht als einzige Zutat auf, die Zutaten des Originalrezepts übernehmen
const titelKey = t => klein(grundname(t));
const original = {};
for (const r of rezepteRoh) if (Array.isArray(r.zutaten) && r.zutaten.length > 1 && !original[titelKey(r.titel)]) original[titelKey(r.titel)] = r.zutaten;
for (const r of rezepteRoh) {
  const z = Array.isArray(r.zutaten) ? r.zutaten : [];
  if (z.length > 1) continue;
  const quelle = original[titelKey(r.titel)] || (z[0] && original[titelKey(z[0].name)]);
  if (quelle) r.zutaten = JSON.parse(JSON.stringify(quelle));
}

// Im Wochenplan pro Tag und Mahlzeit nur ein Rezept (die KI plant manchmal doppelt)
const gesehen = new Set();
const rezepteEindeutig = ctx.modus !== 'wochenplan' ? rezepteRoh : rezepteRoh.filter(r => {
  const k = String(r.tag) + '|' + klein(r.mahlzeit);
  if (gesehen.has(k)) return false;
  gesehen.add(k);
  return true;
});

// Rezepte aufbereiten und pro Mahlzeit auf das Ziel skalieren
const rezepte = rezepteEindeutig.map(r => {
  const zutaten = (Array.isArray(r.zutaten) ? r.zutaten : []).map(zutatAufbereiten).filter(z => z.menge > 0);
  const slot = slotNach[klein(r.mahlzeit)] || slotStandard;
  const tag = /^\d{4}-\d{2}-\d{2}$/.test(String(r.tag || '')) ? r.tag : heute;
  const mitWerten = makros(zutaten).kcal > 0;
  if (mitWerten) {
    skalieren(zutaten, slot, 0.35, 3);
  } else if (zahl(r.kcal) > 0) {
    // Fallback: keine Nährwerte je Zutat, nur Rezeptwerte der KI
    const f = clamp(slot.kcal / zahl(r.kcal), 0.4, 3);
    for (const z of zutaten) z.menge *= f;
  }
  return { r, tag, slot, zutaten, mitWerten };
});

// Feinkorrektur pro Tag (z.B. wenn eine Mahlzeit fehlt oder Faktoren begrenzt wurden)
if (ctx.modus === 'wochenplan') {
  const proTag = {};
  for (const x of rezepte) (proTag[x.tag] = proTag[x.tag] || []).push(x);
  for (const liste of Object.values(proTag)) skalieren(liste.flatMap(x => x.zutaten), ziel, 0.7, 1.4);
}

const r0 = x => Math.round(zahl(x));
const mengeText = z => {
  if (z.einheit === 'g' || z.einheit === 'ml') return z.menge >= 1000 ? (Math.round(z.menge / 100) / 10).toLocaleString('de-DE') + (z.einheit === 'g' ? ' kg' : ' l') : z.menge + ' ' + z.einheit;
  return (z.menge % 1 ? z.menge.toLocaleString('de-DE') : z.menge) + '×';
};

const out = rezepte.map(({ r, tag, zutaten, mitWerten }) => {
  zutaten.forEach(runden);
  const m = mitWerten ? makros(zutaten) : { kcal: zahl(r.kcal), p: zahl(r.protein_g), f: zahl(r.fett_g), kh: zahl(r.kh_g) };
  const kcal = r0(m.kcal), p = r0(m.p), f = r0(m.f), kh = r0(m.kh);
  const schritte = Array.isArray(r.anleitung) ? r.anleitung : String(r.anleitung || '').split('\n').filter(Boolean);
