// Einkaufsliste: Vorratsprodukte nur, soweit der Bestand nicht reicht; Grundzutaten separat
const bedarf = {};
const einkauf = {};
const basis = {};
// „Kartoffeln (festkochend)“, „Kartoffeln (Rest)“ usw. zu einem Posten zusammenfassen
// Zutaten mit REWE-Produkt werden pro Produkt zusammengefasst
const add = (ziel, name, menge, einheit, product_id, packung, rewe = null, gramm = 0) => {
  name = product_id ? name : grundname(name);
  const k = rewe ? 'rewe|' + rewe.rewe_product_id + '|' + einheit : klein(name) + '|' + einheit;
  if (!ziel[k]) ziel[k] = { name, menge: 0, einheit, product_id: product_id || null, packung: 0, rewe, gramm: 0 };
  ziel[k].menge += menge;
  ziel[k].gramm += gramm;
  ziel[k].packung = Math.max(ziel[k].packung, packung || 0);
};
for (const o of out) for (const z of o._zutaten) {
  if (z.product_id != null) bedarf[z.product_id] = (bedarf[z.product_id] || 0) + z.menge;
  else add(z.basis ? basis : einkauf, z.name, z.menge, z.einheit, null, z.packung, z.rewe, z.menge * z.g_pro_einheit);
}
for (const id of Object.keys(bedarf)) {
  const v = inv[id];
  const fehlt = bedarf[id] - (Number(v.menge) || 0);
  if (fehlt > 0.01) add(einkauf, v.name, fehlt, v.einheit, v.product_id, 0);
}
// In kaufbaren Einheiten: Stückware ganze Stück, sonst ganze Packungen (oder grob gerundet, wenn lose Ware)
const gewicht = (x, e) => x >= 1000 ? (Math.round(x / 100) / 10).toLocaleString('de-DE') + (e === 'g' ? ' kg' : ' l') : x + ' ' + e;
const euro = n => Number(n).toFixed(2).replace('.', ',') + ' €';
const reweText = (n, p) => n + '× ' + p.name + ' · ' + euro(zahl(p.preis_aktuell))
  + (p.im_angebot && p.angebot_bis ? ' 🏷️ Angebot bis ' + DateTime.fromISO(p.angebot_bis).toFormat('dd.LL.') : '');
const reweAnzahl = e => {
  const p = e.rewe, g = zahl(p.size_value);
  if (!g) return 1;
  if (p.size_unit === 'Stück') return Math.max(1, Math.ceil((e.einheit === 'stk' ? e.menge : 1) / g - 0.01));
  const benoetigt = (e.einheit === 'g' || e.einheit === 'ml') ? e.menge : e.gramm;
  return Math.max(1, Math.ceil(benoetigt / g - 0.05));
};
const kaufbar = e => {
  if (e.rewe) {
    const n = reweAnzahl(e);
    const preis = zahl(e.rewe.preis_aktuell);
    return { ...e, text: reweText(n, e.rewe), packungen: n, kosten: preis ? Math.round(n * preis * 100) / 100 : null,
      angebot: !!e.rewe.im_angebot, rewe_product_id: e.rewe.rewe_product_id, rewe: undefined };
  }
  if (e.einheit !== 'g' && e.einheit !== 'ml') {
    const n = Math.ceil(e.menge - 0.01);
    if (e.packung >= 2 && n >= e.packung / 2) {
      const p = Math.ceil(n / e.packung);
      return { ...e, menge: n, text: p + '× ' + e.name + ' (' + e.packung + 'er-Packung, du brauchst ' + n + ')' };
    }
    return { ...e, menge: n, text: n + '× ' + e.name };
  }
  if (e.packung > 0) {
    const n = Math.max(1, Math.ceil(e.menge / e.packung - 0.05));
    return { ...e, menge: Math.ceil(e.menge), text: n + '× ' + e.name + ' à ' + gewicht(e.packung, e.einheit) + (n * e.packung - e.menge > e.packung * 0.3 ? ' (du brauchst ca. ' + gewicht(Math.ceil(e.menge / 10) * 10, e.einheit) + ')' : '') };
  }
  const step = e.menge < 200 ? 50 : 100;
  const m = Math.ceil(e.menge / step) * step;
  return { ...e, menge: m, text: 'ca. ' + gewicht(m, e.einheit) + ' ' + e.name };
};
const sortiert = l => Object.values(l).map(kaufbar).sort((x, y) => String(x.name).localeCompare(String(y.name), 'de'));
const einkaufListe = sortiert(einkauf);
const basisListe = sortiert(basis);
const mitPreis = einkaufListe.filter(e => e.kosten != null);
const summe = mitPreis.reduce((acc, e) => acc + e.kosten, 0);
const angebote = einkaufListe.filter(e => e.angebot).length;
const kostenText = mitPreis.length ? 'ca. ' + euro(summe) + ' bei REWE' + (einkaufListe.length > mitPreis.length ? ' (+ ' + (einkaufListe.length - mitPreis.length) + ' Artikel ohne Preis)' : '')
