if (basisListe.length) einkaufText += '\n\n<b>Grundzutaten, bitte prüfen, ob genug da ist</b>\n' + basisListe.map(e => '• ' + esc(e.text)).join('\n');
einkaufText = einkaufText.slice(0, 4000);

// Wochenübersicht mit Ist/Ziel je Tag
const reihenfolge = { 'frühstück': 0, 'mittag': 1, 'abend': 2, 'snack': 3, 'snack 2': 4 };
const tage = {};
for (const o of out) (tage[o.geplant_fuer] = tage[o.geplant_fuer] || []).push(o);
let uebersicht = (data.hinweis ? '💡 ' + esc(data.hinweis) + '\n\n' : '') + '<b>📅 Dein Wochenplan</b>\n' + esc(ctx.ziele_text) + '\n'
